                else:
                    table[j][k] = T[j]

    LEAD = max(64, nflagblocks + 8)
    nonce, ct = svc.batch([b"\x00" * (16 * LEAD)])[0]
    record(nonce, [ct[16 * i:16 * i + 16] for i in range(LEAD)])

    need = set()
    for i in range(nflagblocks):
        x = fn + i.to_bytes(4, "big")
        for j in range(16):
            need.add((j, x[j]))
    if verify_pt is not None:
        vblocks = (len(verify_pt) + 15) // 16
        # extra counters needed for verification -> ask for them via a long query too
        if vblocks > LEAD:
            nonce, ct = svc.batch([b"\x00" * (16 * vblocks)])[0]
            record(nonce, [ct[16 * i:16 * i + 16] for i in range(vblocks)])
    def missing():
        return [t for t in need if t[1] not in table[t[0]]]
    while missing() and svc.queries <= 4000:
        for nn, cc in svc.batch([b"\x00" * 16] * 128):
            record(nn, [cc[:16]])
    assert not missing(), missing()
    assert not mism, mism[:4]

    out = b""
    for i in range(nflagblocks):
        x = fn + i.to_bytes(4, "big")
        T = bytes(table[j][x[j]] for j in range(16))
        out += bytes(a ^ b for a, b in zip(bytes(S.L(T)), svc.flag_ct[16 * i:16 * i + 16]))

    vres = None
    if verify_pt is not None:
        P = verify_pt
        vb = (len(P) + 15) // 16
        ok = None
        for _ in range(10):
            nonce, ct = svc.batch([P])[0]
            xs = [nonce + i.to_bytes(4, "big") for i in range(vb)]
            if all(x[j] in table[j] for x in xs for j in range(16)):
                pred = b""
                for i, x in enumerate(xs):
                    T = bytes(table[j][x[j]] for j in range(16))
                    pred += bytes(S.L(T))
                pred = bytes(a ^ b for a, b in zip(pred, P))
                ok = (pred == ct)
                vres = (ok, len(P), vb)
                if ok:
                    break
            else:
                for nn, cc in svc.batch([b"\x00" * 16] * 64):
                    record(nn, [cc[:16]])
        assert ok, "multi-block chosen-plaintext verification FAILED"
    svc.s.close()
    return out, svc.queries, vres

def main():
    results = []
    for run in (1, 2):
        out, q, v = collect_and_decrypt(verify_pt=b"ABCDEFGHIJKLMNOP0123456789abcdefXYZ{|}~ !\"#$%&", target_extra=3)
        print("[run %d] queries=%d multiblock-verify=%s" % (run, q, v))
        print("[run %d] plaintext=%r" % (run, out))
        results.append(out)
        assert out == FLAG, out
    assert results[0] == results[1] == FLAG
    print("[ok] two independent connections (distinct random keys) both recover:")
    print("FLAG:", FLAG.decode().strip())

if __name__ == "__main__":
    main()
